INSERT INTO `products` (`id`, `woo_id`, `title`, `shortdesc`, `excerpt`, `description`, `images`, `product_type`, `status`, `created_at`, `updated_at`) VALUES
(111, 10127, 'هم زن کاسه‌ای جی‌سان مدل GI-901CS', NULL, NULL, '\'- هم زن کاسه ای حرفه ای\r\n\r\n\r\n\r\n- قابلیت چرخش کاسه\r\n\r\n\r\n\r\n- بدنه استیل مشکی\r\n\r\n\r\n\r\n-با قدرت 200 وات', '[\"products\\/VUICU7FimdPQxbQUTJdiV5iAc720OnjplM6gtdiU.jpg\"]', 'variable', 'published', '2026-05-20 01:43:13', '2026-05-25 02:56:46'),
(113, 10143, 'اسپیلت دیواری سرد و گرم 12 هزار جی‌سان مدل MGS12H1', NULL, NULL, 'اسپیلت سرد و گرم مدل MGS12H1\r\n\nکولر گازی دو تکه که با نام کولر گازی اسپلیت هم شناخته می‌شود، جدیدترین نسل سیستم‌های تهویه مطبوع است. دلیل این نام گذاری این نوع سیستم‌ها در ساختار دو تکه ای آن است. این نوع ازکولرهای گازی دارای دو یا بیشتر از دو قسمت هستند. یک یا چند قسمت در داخل ساختمان و یک قسمت در خارج ساختمان قرار می‌گیرد. این سیستم‌ها در دو نوع سرمایشی و سرمایشی/گرمایشی در بازار موجود هستند. نوع اول فقط برای سرد کردن فضا (برای فصل تابستان) و نوع دوم برای سرد یا گرم کردن فضا (چهار فصل) می‌توانند مورد استفاده واقع شوند.\r\n\nویژگی اسپیلت سرد و گرم مدل MGS12H1 :\r\n\n\r\n\n 	سیستم هوشمند تهویه مطبوع گردش هوای پاک\r\n\n 	حالت کاهش مصرف انرژی (eco mode)\r\n\n 	حالت پرتاب باد فوق قوی (turbo)\r\n\n 	کندانسور طلایی\r\n\n 	سیستم نگه داشتن میزان دمای محیط در حالت مطلوب هنگام خواب کم صدا\r\n\n\r\n\nمشخصات اسپیلت سرد و گرم مدل MGS12H1 :\r\n\n&nbsp;\r\n\n\r\n\n\r\n\n\r\n\n            مدل\r\n\n            ظرفیت سرمایشی\r\n\n            ظرفیت گرمایشی\r\n\n            نوع برق مصرفی\r\n\n            توان مصرفی (سرمایشی)\r\n\n            توان مصرفی (گرمایشی)\r\n\n            آمپر مصرفی (سرمایشی)\r\n\n            آمپر مصرفی (گرمایشی)\r\n\n            نوع کمپرسور\r\n\n            ابعاد یونیت داخلی\r\n\n            ابعاد یونیت خارجی\r\n\n            اندازه لوله مایع\r\n\n            اندازه لوله گاز\r\n\n            میزان نویز یونیت داخلی\r\n\n            میزان نویز یونیت خارجی\r\n\n\r\n\n\r\n\n            MGS 12H1\r\n\n12000\r\n\n12500\r\n\nتک فاز\r\n\n1199\r\n\n1015\r\n\n5/3\r\n\n4/5\r\n\nروتاری\r\n\n285*194*805\r\n\n495*270*720\r\n\n6/35 (1/4)\r\n\n12/7 (3/8)\r\n\n28/5\r\n\n55/5', '[\"products\\/504f6789-88f9-4e91-988e-7b6acf100d58.jpg\",\"products\\/5fb5cd15-92f6-4bfa-b9d7-ac699e9e7c8e.jpg\"]', 'simple', 'published', '2026-05-20 01:43:20', '2026-05-23 10:16:55'),
